const p = msg.payload;
const timestamp = new Date(p && p.timestamp_utc);
const balanceId = String((p && p.balance_id) || "dp15m");
if (!p || !Number.isFinite(Number(p.weight_g)) || !Number.isFinite(timestamp.getTime()) || !/^[A-Za-z0-9_-]{1,64}$/.test(balanceId) || typeof p.stable !== "boolean") {
    msg.statusCode = 400;
    msg.payload = "Mesure invalide";
    return [null, msg];
}
const token = env.get("INFLUX_TOKEN");
if (!token) {
    msg.statusCode = 503;
    msg.payload = "Jeton InfluxDB non configure";
    return [null, msg];
}
const weight = Number(p.weight_g);
msg.method = "POST";
msg.url = "http://127.0.0.1:8086/api/v2/write?org=ird&bucket=sondes&precision=ms";
msg.headers = {"Authorization": "Token " + token, "Content-Type": "text/plain; charset=utf-8"};
msg.payload = `balance,balance_id=${balanceId} weight_g=${weight},stable=${p.stable} ${timestamp.getTime()}`;
return [msg, null];

if (msg.statusCode >= 200 && msg.statusCode < 300) {
    msg.statusCode = 204;
    msg.payload = "";
} else {
    node.warn("Ecriture InfluxDB refusee, statut " + msg.statusCode);
    msg.statusCode = 502;
    msg.payload = "Ecriture InfluxDB impossible";
}
return msg;
